// Accepts the webhook body (or a raw item when run manually) and validates the ticker.
const j = $input.first().json;
const fromWebhook = j.body !== undefined && j.headers !== undefined;
const src = fromWebhook ? (j.body || {}) : j;
const rawTicker = String(src.ticker ?? src.Ticker ?? '').trim().toUpperCase();
const rawPeers = String(src.peers ?? src['Peers (optional)'] ?? '');
const valid = /^[A-Z0-9.\-^=&]{1,20}$/;
const peers = rawPeers.split(/[\s,;]+/).map(p => p.trim().toUpperCase()).filter(p => valid.test(p) && p !== rawTicker).slice(0, 8);
return [{ json: {
  ticker: rawTicker,
  peers: peers.join(','),
  valid: valid.test(rawTicker),
  error: valid.test(rawTicker) ? null : `"${rawTicker || '(empty)'}" is not a valid ticker symbol.`,
  source: ['site', 'form', 'api'].includes(src.source) ? src.source : 'api',
  requested_at: new Date().toISOString(),
  news_query: encodeURIComponent(rawTicker.replace(/\.(NS|BO)$/, '') + ' stock'),
  news_locale: /\.(NS|BO)$/.test(rawTicker) ? 'hl=en-IN&gl=IN&ceid=IN:en' : 'hl=en-US&gl=US&ceid=US:en',
} }];

const ticker = $('Normalize input').first().json.ticker;
const map = $input.first().json || {};
if (map.error) return [{ json: { cik: null, note: 'SEC ticker map unavailable' } }];
const wanted = [ticker, ticker.replace('.', '-')];
for (const k of Object.keys(map)) {
  const r = map[k];
  if (r && r.ticker && wanted.includes(String(r.ticker).toUpperCase())) {
    return [{ json: { cik: String(r.cik_str).padStart(10, '0'), entity: r.title } }];
  }
}
return [{ json: { cik: null, note: `${ticker} is not an SEC registrant (non-US listing or ADR under another symbol).` } }];

const ref = $('SEC: resolve CIK').first().json;
const r = $input.first().json || {};
const ITEMS = { '1.01': 'Material agreement', '2.02': 'Results of operations', '2.05': 'Restructuring costs',
  '5.02': 'Director/officer change', '5.07': 'Shareholder vote', '7.01': 'Reg FD disclosure', '8.01': 'Other events',
  '9.01': 'Financial statements & exhibits', '2.01': 'Acquisition/disposition', '1.02': 'Agreement terminated' };
if (!ref.cik || r.error || !r.filings || !r.filings.recent) {
  return [{ json: { filings: { cik: ref.cik, entity: ref.entity || null, recent: [],
    note: ref.note || 'SEC submissions request failed.' } } }];
}
const f = r.filings.recent;
const skip = new Set(['3', '4', '5', '144', 'FWP', '424B2', '424B3', '424B5', 'SC 13G/A', 'S-8 POS']);
const cutoff = Date.now() - 90 * 864e5;
let insider90 = 0;
const recent = [];
for (let i = 0; i < f.form.length; i++) {
  if (f.form[i] === '4' && Date.parse(f.filingDate[i]) >= cutoff) insider90++;
  if (skip.has(f.form[i]) || recent.length >= 30) continue;
  const acc = String(f.accessionNumber[i] || '').replace(/-/g, '');
  const items = String(f.items?.[i] || '').split(',').map(s => s.trim()).filter(Boolean);
  const desc = f.form[i] === '8-K' && items.length ? items.map(x => ITEMS[x] || `Item ${x}`).join('; ') : (f.primaryDocDescription?.[i] || '');
  recent.push({ form: f.form[i], date: f.filingDate[i], report_date: f.reportDate?.[i] || null, description: desc,
    url: acc && f.primaryDocument?.[i] ? `https://www.sec.gov/Archives/edgar/data/${parseInt(ref.cik, 10)}/${acc}/${f.primaryDocument[i]}` : null });
}
return [{ json: { filings: { cik: ref.cik, entity: r.name || ref.entity, sic: r.sicDescription || null,
  fiscal_year_end: r.fiscalYearEnd || null, recent, insider_filings_90d: insider90 } } }];

const out = [];
for (const { json: j } of $input.all()) {
  if (!j || !j.title || j.error) continue;
  let host = '';
  try { host = new URL(j.link).hostname; } catch (e) {}
  const google = host.includes('news.google.');
  // Google News titles end with " - Publisher"
  const m = google ? String(j.title).match(/^(.*)\s+-\s+([^-]{2,60})$/) : null;
  out.push({ title: m ? m[1] : j.title, link: j.link, published: j.isoDate || j.pubDate,
    source: m ? m[2] : (j.creator || (google ? 'Google News' : 'Yahoo Finance')),
    summary: google ? '' : (j.contentSnippet || ''), feed: google ? 'google-news' : 'yahoo-rss' });
}
return [{ json: { news: out.slice(0, 60) } }];

const input = $('Normalize input').first().json;
const items = $input.all().map(i => i.json || {});
const pick = (k) => { const hit = items.find(j => j[k] !== undefined); return hit ? hit[k] : undefined; };
const market = pick('market');
if (!market || !market.history || !market.history.length) {
  const err = items.find(j => j.error)?.error;
  let msg = typeof err === 'string' ? err : (err?.message || err?.description || '');
  const detail = String(msg).match(/detail\\*"\s*:\s*\\*"(.*?)\\*"/);
  if (detail) msg = detail[1];
  return [{ json: { ok: false, source: input.source, ticker: input.ticker,
    error: `Could not load market data for ${input.ticker}. ${msg}`.trim() } }];
}
return [{ json: { ok: true, source: input.source, ticker: input.ticker,
  request: { ticker: input.ticker, market, filings: pick('filings') || null, news: pick('news') || [] } } }];

const a = $input.first().json.analysis;
const SYSTEM = [
  'You are a careful sell-side equity research analyst writing for a professional reader.',
  'Use ONLY the facts and numbers in the brief. Never invent figures, dates, products, events or price targets.',
  'Quote specific numbers from the brief where they support a point. Be concise, neutral and specific; no hype.',
  'Do not give buy/sell/hold advice. Write in plain English. Return JSON that matches the schema exactly.',
].join(' ');
const str = { type: 'string' };
const list = { type: 'array', items: { type: 'string' }, minItems: 2, maxItems: 5 };
const obj = (props) => ({ type: 'object', properties: props, required: Object.keys(props) });
const req = (schema, task, brief) => ({
  stream: false, think: false, format: schema,
  messages: [ { role: 'system', content: SYSTEM }, { role: 'user', content: `${task}\n\n=== BRIEF ===\n${brief}` } ],
});
return [{ json: {
  fundamental: req(obj({ business_overview: str, financial_performance: str, valuation: str, peer_positioning: str, filings_highlights: str }),
    'Write the fundamentals section. business_overview: 2-3 sentences on what the company does. financial_performance: 3-4 sentences on growth, margins and cash flow trends across the annual figures. valuation: 2-3 sentences on multiples and FCF yield. peer_positioning: 2-3 sentences comparing multiples, margins and growth to the peers listed. filings_highlights: 1-2 sentences on the recent SEC filings (say so if none).',
    a.llm_briefs.fundamentals),
  technical: req(obj({ trend_and_momentum: str, key_levels: str, news_sentiment: str, risks: list, catalysts: list }),
    'Write the technicals & news section. trend_and_momentum: 3-4 sentences interpreting the moving averages, RSI, MACD and returns. key_levels: 1-2 sentences on support/resistance and the 200-day average. news_sentiment: 2-3 sentences summarising what the headlines are about and their tone. risks: 3-5 short bullet sentences. catalysts: 2-4 short bullet sentences (upcoming or ongoing drivers mentioned in the brief or headlines).',
    a.llm_briefs.technicals),
  summary_brief: a.llm_briefs.summary,
} }];

const p = $('Prepare LLM prompts').first().json;
const content = (name) => {
  const j = $(name).first().json || {};
  return String(j.message?.content || '').replace(/<think>[\s\S]*?<\/think>/g, '').slice(0, 6000);
};
const str = { type: 'string' };
const list = { type: 'array', items: { type: 'string' }, minItems: 2, maxItems: 5 };
const schema = { type: 'object', required: ['headline', 'executive_summary', 'bull_case', 'bear_case', 'stance', 'confidence', 'watch_items'],
  properties: { headline: str, executive_summary: str, bull_case: list, bear_case: list,
    stance: { type: 'string', enum: ['Constructive', 'Neutral', 'Cautious'] },
    confidence: { type: 'string', enum: ['Low', 'Medium', 'High'] }, watch_items: list } };
const task = 'You are the lead analyst. Using the brief and the two draft sections, write: headline (max 12 words, specific, no clickbait); ' +
  'executive_summary (4-5 sentences covering business quality, valuation, trend and news); bull_case and bear_case (3-4 bullets each, each citing a number); ' +
  'stance (Constructive, Neutral or Cautious — an overall research tone, not trading advice); confidence (Low, Medium or High, based on data completeness and agreement between signals); ' +
  'watch_items (2-4 things to monitor).';
const brief = `${p.summary_brief}\n=== DRAFT: FUNDAMENTALS ===\n${content('LLM: fundamentals analyst')}\n=== DRAFT: TECHNICALS & NEWS ===\n${content('LLM: technicals & news analyst')}`;
return [{ json: { summary: { stream: false, think: false, format: schema, messages: [
  { role: 'system', content: p.fundamental.messages[0].content }, { role: 'user', content: `${task}\n\n=== BRIEF ===\n${brief}` } ] } } }];

const r = $input.first().json;
return [{ json: { ok: true, source: $('Normalize input').first().json.source, ticker: $('Normalize input').first().json.ticker,
  id: r.id, report_url: r.report_url, pdf_url: r.pdf_url, stance: r.stance, headline: r.headline, llm_coverage: r.llm_coverage } }];
